ttribute['id']) ?>" value="1" <?= (int)($configured['is_required']??0)===1?'checked':'' ?>> Obligatorio</label><label><input type="checkbox" name="visible_<?= e($attribute['id']) ?>" value="1" <?= $configured===null||(int)($configured['is_visible']??0)===1?'checked':'' ?>> Visible</label><label><input type="checkbox" name="filterable_<?= e($attribute['id']) ?>" value="1" <?= (int)($configured['is_filterable']??0)===1?'checked':'' ?>> Filtro</label></div></article><?php endforeach?></div></fieldset><button class="admin-primary-button" type="submit"><?= $item===null?'Crear categoría inactiva':'Guardar cambios' ?></button></form></section>
